package com.aicharacter.v3;import java.util.*;
/** Assertion-style V0.95 smoke suite. PASS is emitted only from evaluated booleans. */
public final class V095DevTest{private V095DevTest(){}
 public static String run(WorldState original){StringBuilder b=new StringBuilder("V095 DEV TEST\n");long now=System.currentTimeMillis();WorldState s=original;test(b,"A cat persists",s.catState!=null&&s.catState.areaId!=null);test(b,"G attach range",!("girl".equals(s.catState.attachedToEntity)&&!sameArea(s)));test(b,"K carried suppress search",!(s.catState.carryKnownByGirl&&"girl".equals(s.catState.attachedToEntity)&&GirlCatSearchEngine.shouldSearch(s,now)));test(b,"L search planner boundary",!GirlCatSearchEngine.trace(s).contains("catX="));test(b,"O local perception boundary",!GirlCatSearchEngine.canPerceiveCat(s)||sameArea(s));int before=s.godInbox.size();WorldHistoryEntry fake=new WorldHistoryEntry(now,"evt_test_normal","WEATHER","test","ordinary weather");GodAttentionEngine.consume(s,fake);test(b,"V no fake search message",s.godInbox.size()==before);WorldHistoryEntry search=WorldEventBus.publishId(s,now,"evt_v095_search_test","GIRL_STARTED_SEARCH","test","grounded test search");test(b,"U grounded search God",s.godInbox.size()==before+1&&s.godInbox.get(s.godInbox.size()-1).sourceEventId.equals(search.eventId));int once=s.godInbox.size();GodAttentionEngine.consume(s,search);test(b,"Y God dedup",s.godInbox.size()==once);test(b,"AQ God source grounding",GodAttentionEngine.grounded(s,s.godInbox.get(s.godInbox.size()-1)));test(b,"AO contradiction",StateInvariantChecker.valid(s));test(b,"AS visual groundY",s.world!=null&&s.world.areaAt(s.haruX)!=null&&s.world.areaAt(s.haruX).groundY>0);test(b,"AK canonical simulation timestamp",s.lastSimulatedAt>=0);return b.toString();}
 private static boolean sameArea(WorldState s){WorldArea a=s.world.areaAt(s.catState.x),g=s.world.areaAt(s.haruX);return a!=null&&g!=null&&a.id.equals(g.id);}
 private static void test(StringBuilder b,String name,boolean ok){b.append(name).append(": ").append(ok?"PASS":"FAIL").append('\n');}
}
